/* ? BLOCK DESCRIPTION==> css reset */
@layer reset {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
    scrollbar-width: thin;
    scroll-behavior: smooth;
    font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI',
      Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue',
      sans-serif;
  }
  * {
    scroll-margin-block: 64px !important;
  }

  ::-webkit-scrollbar {
    width: 7px;
  }

  ::-webkit-scrollbar-thumb {
    background: rgba(var(--v-theme-border));
    border-radius: 5px;
    margin: 0px auto;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #aaa;
  }
  ::-webkit-scrollbar-track {
    background: transparent !important;
  }

  body {
    margin: unset;
  }

  button,
  input,
  textarea,
  select {
    font: inherit;
  }

  img,
  picture,
  svg,
  canvas {
    display: block;
    max-inline-size: 100%;
    block-size: auto;
  }

  ::selection {
    background: rgba(var(--v-theme-primary-dark));
    color: #fff;
  }
  input[type='search']::-webkit-search-cancel-button {
    -webkit-appearance: none;
    height: 14px;
    width: 14px;
    display: block;
    background-image: url(data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAB4AAAAeCAYAAAA7MK6iAAAAn0lEQVR42u3UMQrDMBBEUZ9WfQqDmm22EaTyjRMHAlM5K+Y7lb0wnUZPIKHlnutOa+25Z4D++MRBX98MD1V/trSppLKHqj9TTBWKcoUqffbUcbBBEhTjBOV4ja4l4OIAZThEOV6jHO8ARXD+gPPvKMABinGOrnu6gTNUawrcQKNCAQ7QeTxORzle3+sDfjJpPCqhJh7GixZq4rHcc9l5A9qZ+WeBhgEuAAAAAElFTkSuQmCC);
    background-repeat: no-repeat;
    background-size: 14px;
    cursor: pointer;
  }
  input[type='checkbox'],
  input[type='radio'],
  input[type='range'] {
    accent-color: rgba(var(--v-theme-primary)) !important;
  }

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }
}

/* ? BLOCK DECRIPTION==> general classes */
.system-bg {
  background: url('~/assets/images/bg/white.png') !important;
  background-position: center !important;
  background-size: contain !important;
  background-color: rgba(var(--v-theme-background)) !important;
}
.light-link {
  text-decoration: none;
  color: currentColor;
  cursor: pointer;
  opacity: 0.7;
}
.light-link:hover {
  opacity: 1;
}
.card-outlined {
  border: 1px solid rgba(var(--v-theme-border)) !important;
}
.menu-list {
  -webkit-backdrop-filter: blur(25px) !important;
