  background-color: hsla(204, 33%, 100%, 0.65) !important;
}
.product-sm-card {
  width: clamp(280px, 30%, 280px) !important;
  height: 120px;
}
.hide-scrollbar {
  -ms-overflow-style: none !important;
  scrollbar-width: none !important;
}
.hide-scrollbar::-webkit-scrollbar {
  display: none !important;
}
.prod-title {
  word-wrap: break-word;
}
.prod-image-fit {
  object-fit: cover;
  height: 100%;
  aspect-ratio: 1/1;
}

.skeleton {
  background-color: #eee !important;
